//! The embedded catalog: every entry folder compiled into the app.
//!
//! `embedded::FILES` lists the catalog files (generated by `scripts/gen-store-catalog.mjs`).
//! `load` turns any list of `(path, text)` pairs into entries. A folder that breaks a rule is
//! refused with its messages and the other folders still load, so one bad entry never hides the
//! rest and never reaches the Store as data. `all` parses the shipped files once. The stricter
//! rules that need the whole catalog (fixtures, publishers, wording) are in `check.rs`.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use sha2::{Digest, Sha256};

use super::embedded;
use super::entry::{parse_entry, validate_entry, EntryFile};
use crate::tui::declarative::parse_definition;
use crate::tui::install::InstallSpec;

/// One catalog entry: its card data, its definition text (absent for built-in code agents) and
/// its fixture files as `(file name, text)`, in name order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CatalogEntry {
    pub entry: EntryFile,
    pub definition_text: Option<String>,
    pub fixtures: Vec<(String, String)>,
}

impl CatalogEntry {
    /// The name a card and an install title show: the definition's `agent.label` when it has one.
    /// A built-in agent has no definition, so it shows the label its registered TUI profile shows
    /// everywhere else (`tui::descriptor_for`). Anything else falls back to the vendor's name.
    pub fn label(&self) -> String {
        let defined = match self.definition_text.as_deref() {
            Some(text) => parse_definition(text).ok().map(|definition| definition.agent.label.trim().to_string()),
            None => crate::tui::descriptor_for(&self.entry.store.id).map(|descriptor| descriptor.label.trim().to_string()),
        }
        .filter(|label| !label.is_empty());
        defined.unwrap_or_else(|| self.entry.vendor.name.clone())
    }
}

/// What `load` made of a list of files.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Loaded {
    /// The valid entries, sorted by id.
    pub entries: Vec<CatalogEntry>,
    /// One message per problem. Each starts with the file path, so the person can find it.
    pub problems: Vec<String>,
}

/// Turns `(path, text)` pairs (`agents/<id>/...`) into entries. Any file that is not part of an
/// entry's shape, a duplicate, or a broken folder makes that whole folder a problem.
pub fn load(files: &[(&str, &str)]) -> Loaded {
    let mut folders: BTreeMap<&str, Vec<(&str, &str)>> = BTreeMap::new();
    let mut problems = Vec::new();
    for &(path, text) in files {
        match path.strip_prefix("agents/").and_then(|rest| rest.split_once('/')) {
            Some((id, inside)) => folders.entry(id).or_default().push((inside, text)),
            None => problems.push(format!("{path}: catalog files live under agents/<id>/")),
        }
    }
    let mut entries = Vec::new();
    for (id, members) in &folders {
        match read_folder(id, members) {
            Ok(entry) => entries.push(entry),
            Err(found) => problems.extend(found),
        }
    }
    Loaded { entries, problems }
}

/// The entry in one folder `agents/<id>/`. `members` are `(path inside the folder, text)`.
fn read_folder(id: &str, members: &[(&str, &str)]) -> Result<CatalogEntry, Vec<String>> {
    let base = format!("agents/{id}");
    let mut problems = Vec::new();
    let mut entry_text: Option<&str> = None;
    let mut definition_text: Option<&str> = None;
    let mut fixtures: Vec<(String, String)> = Vec::new();
    for &(inside, text) in members {
        let file = format!("{base}/{inside}");
        if inside == "entry.toml" {
            if entry_text.replace(text).is_some() {
                problems.push(format!("{file}: listed twice"));
            }
        } else if inside == "definition.toml" {
            if definition_text.replace(text).is_some() {
                problems.push(format!("{file}: listed twice"));
            }
        } else if let Some(name) = inside.strip_prefix("fixtures/").filter(|n| !n.is_empty() && !n.contains('/')) {
            if fixtures.iter().any(|(n, _)| n == name) {
                problems.push(format!("{file}: listed twice"));
            } else {
                fixtures.push((name.to_string(), text.to_string()));
            }
        } else {
            problems.push(format!("{file}: not a catalog file (use entry.toml, definition.toml or fixtures/<name>)"));
        }
    }

    let entry = match entry_text {
        None => {
            problems.push(format!("{base}/entry.toml: file missing"));
            None
        }
        Some(text) => match parse_entry(text) {
            Ok(entry) => Some(entry),
            Err(message) => {
                problems.push(format!("{base}/entry.toml: {message}"));
                None
            }
        },
    };
    let Some(entry) = entry else { return Err(problems) };

    for message in validate_entry(&entry) {
        problems.push(format!("{base}/entry.toml: {message}"));
    }
    if entry.store.id != id {
        problems.push(format!(
            "{base}/entry.toml: store.id `{}` must equal the folder name `{id}`",
            entry.store.id
        ));
    }
    match (entry.store.builtin, definition_text) {
        (true, Some(_)) => problems.push(format!("{base}/definition.toml: a built-in entry has no definition file")),
        (true, None) if !fixtures.is_empty() => {
            problems.push(format!("{base}/fixtures: a built-in entry has no fixtures"));
        }
        (false, None) => problems.push(format!("{base}/definition.toml: file missing (a store entry needs one)")),
        _ => {}
    }
    if let Some(text) = definition_text {
        match parse_definition(text) {
            Ok(definition) => {
                if definition.agent.id != id {
                    problems.push(format!(
                        "{base}/definition.toml: agent.id `{}` must equal the folder name `{id}`",
                        definition.agent.id
                    ));
                }
                let windows = definition.install.as_ref().and_then(|table| table.windows.as_ref());
                if let Some(Err(message)) = windows.map(InstallSpec::validate) {
                    problems.push(format!("{base}/definition.toml: {message}"));
                }
            }
            Err(error) => problems.push(format!("{base}/definition.toml: {error}")),
        }
    }

    if !problems.is_empty() {
        return Err(problems);
    }
    Ok(CatalogEntry {
        entry,
        definition_text: definition_text.map(str::to_string),
        fixtures,
    })
}

/// The shipped catalog, parsed once from the files the build embeds.
fn shipped() -> &'static Loaded {
    static SHIPPED: OnceLock<Loaded> = OnceLock::new();
    SHIPPED.get_or_init(|| load(embedded::FILES))
}

/// Every valid shipped entry, sorted by id.
pub fn all() -> &'static [CatalogEntry] {
    &shipped().entries
}

/// The problems found in the shipped files. Empty when the catalog is clean (a test checks it).
pub fn problems() -> &'static [String] {
    &shipped().problems
}

/// The shipped entry with this id, or `None` (an unknown id is never an error here).
pub fn get(id: &str) -> Option<&'static CatalogEntry> {
    find_in(all(), id)
}

fn find_in<'a>(entries: &'a [CatalogEntry], id: &str) -> Option<&'a CatalogEntry> {
    entries.iter().find(|e| e.entry.store.id == id)
}

/// The shipped definition text of one entry, or `None` for a built-in or unknown id.
pub fn embedded_definition(id: &str) -> Option<&'static str> {
    get(id)?.definition_text.as_deref()
}

/// The Windows install spec from the shipped definition, only when it passes `validate`.
pub fn install_spec(id: &str) -> Option<InstallSpec> {
    install_spec_of(get(id)?)
}

/// The Windows install spec of one entry (see `install_spec`).
pub fn install_spec_of(entry: &CatalogEntry) -> Option<InstallSpec> {
    windows_spec(entry.definition_text.as_deref()?)
}

/// The `[install.windows]` table of one definition text, when it is present and valid.
fn windows_spec(definition_text: &str) -> Option<InstallSpec> {
    let definition = parse_definition(definition_text).ok()?;
    let spec = definition.install?.windows?;
    spec.validate().is_ok().then_some(spec)
}

/// Eight hex digits: the first 32 bits of the SHA-256 over the shipped files.
pub fn catalog_version() -> String {
    version_of(embedded::FILES)
}

/// The version of any file list. Files are hashed in path order, and each path and text is
/// length-prefixed, so a change to any byte (or a moved byte between two files) changes it.
pub fn version_of(files: &[(&str, &str)]) -> String {
    let mut sorted: Vec<(&str, &str)> = files.to_vec();
    sorted.sort_by(|a, b| a.0.cmp(b.0));
    let mut hash = Sha256::new();
    for (path, text) in sorted {
        hash.update((path.len() as u64).to_le_bytes());
        hash.update(path.as_bytes());
        hash.update((text.len() as u64).to_le_bytes());
        hash.update(text.as_bytes());
    }
    hash.finalize().iter().take(4).map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A valid `entry.toml` for `id`.
    fn entry_toml(id: &str, builtin: bool) -> String {
        format!(
            r#"schema_version = 1

[store]
id = "{id}"
tagline = "A test agent."
tier = "starter"
builtin = {builtin}
categories = ["general"]
status = "active"
first_listed = "2026-10-28"

[vendor]
name = "Test Vendor"
homepage = "https://example.com/{id}"
license = "Apache-2.0"
license_kind = "open_source"

[sign_in]
kind = "none"
summary = "No sign-in needed."

[checked]
date = "2026-10-28"
version = "1.0.0"
how = "vendor_docs"
windows_tested = false
"#
        )
    }

    /// A small `definition.toml` for `id` with a valid Windows npm install.
    fn definition_toml(id: &str) -> String {
        format!(
            "schema_version = 1\n\n[agent]\nid = \"{id}\"\nlabel = \"Test {id}\"\n\n[binary]\nnames = [\"{id}\"]\n\n\
             [install.windows]\nsource = \"https://example.com/{id}\"\nnpm = \"test-{id}-cli\"\n"
        )
    }

    /// The files of one store entry (entry, definition, one fixture), as the generator lists them.
    fn tree(id: &str) -> Vec<(String, String)> {
        vec![
            (format!("agents/{id}/entry.toml"), entry_toml(id, false)),
            (format!("agents/{id}/definition.toml"), definition_toml(id)),
            (format!("agents/{id}/fixtures/idle.txt"), "idle screen\n".to_string()),
        ]
    }

    fn refs(files: &[(String, String)]) -> Vec<(&str, &str)> {
        files.iter().map(|(path, text)| (path.as_str(), text.as_str())).collect()
    }

    fn ids(loaded: &Loaded) -> Vec<&str> {
        loaded.entries.iter().map(|e| e.entry.store.id.as_str()).collect()
    }

    #[test]
    fn a_tree_loads_into_entries_with_their_definition_and_fixtures() {
        let mut files = tree("alpha");
        files.extend(tree("beta"));
        let loaded = load(&refs(&files));
        assert!(loaded.problems.is_empty(), "{:?}", loaded.problems);
        assert_eq!(ids(&loaded), ["alpha", "beta"]);
        let alpha = &loaded.entries[0];
        assert!(alpha.definition_text.as_deref().is_some_and(|t| t.contains("id = \"alpha\"")));
        assert_eq!(alpha.fixtures, vec![("idle.txt".to_string(), "idle screen\n".to_string())]);
    }

    #[test]
    fn entries_come_back_sorted_by_id_whatever_the_input_order() {
        let mut files = tree("beta");
        files.extend(tree("alpha"));
        assert_eq!(ids(&load(&refs(&files))), ["alpha", "beta"]);
    }

    #[test]
    fn a_built_in_entry_loads_with_no_definition_and_no_fixtures() {
        let files = vec![("agents/claude/entry.toml".to_string(), entry_toml("claude", true))];
        let loaded = load(&refs(&files));
        assert!(loaded.problems.is_empty(), "{:?}", loaded.problems);
        assert_eq!(loaded.entries[0].definition_text, None);
        assert!(loaded.entries[0].fixtures.is_empty());
    }

    #[test]
    fn a_store_entry_without_a_definition_is_refused() {
        let files = vec![("agents/alpha/entry.toml".to_string(), entry_toml("alpha", false))];
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems.iter().any(|p| p.starts_with("agents/alpha/definition.toml:")), "{:?}", loaded.problems);
    }

    #[test]
    fn a_built_in_entry_with_a_definition_is_refused() {
        let mut files = tree("claude");
        files[0] = ("agents/claude/entry.toml".to_string(), entry_toml("claude", true));
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems.iter().any(|p| p.contains("built-in entry has no definition")), "{:?}", loaded.problems);
    }

    #[test]
    fn a_folder_name_that_differs_from_the_store_id_is_refused() {
        let files = vec![
            ("agents/gamma/entry.toml".to_string(), entry_toml("alpha", false)),
            ("agents/gamma/definition.toml".to_string(), definition_toml("gamma")),
        ];
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems.iter().any(|p| p.contains("must equal the folder name `gamma`")), "{:?}", loaded.problems);
    }

    #[test]
    fn a_bad_entry_is_refused_and_the_other_entries_still_load() {
        let mut bad = tree("alpha");
        bad[0].1 = bad[0].1.replace("tier = \"starter\"", "tier = \"gold\"");
        bad.extend(tree("beta"));
        let loaded = load(&refs(&bad));
        assert_eq!(ids(&loaded), ["beta"]);
        assert!(
            loaded.problems.iter().any(|p| p.starts_with("agents/alpha/entry.toml:") && p.contains("store.tier")),
            "{:?}",
            loaded.problems
        );
    }

    #[test]
    fn a_stray_file_in_an_entry_folder_refuses_that_entry() {
        let mut files = tree("alpha");
        files.push(("agents/alpha/notes.md".to_string(), "x".to_string()));
        files.push(("agents/alpha/fixtures/deep/x.txt".to_string(), "x".to_string()));
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert_eq!(loaded.problems.len(), 2, "{:?}", loaded.problems);
    }

    #[test]
    fn a_file_outside_agents_is_refused() {
        let files = vec![("other/entry.toml".to_string(), "x = 1".to_string())];
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems[0].starts_with("other/entry.toml:"), "{:?}", loaded.problems);
    }

    #[test]
    fn a_file_listed_twice_refuses_the_entry() {
        let mut files = tree("alpha");
        files.extend(tree("alpha"));
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems.iter().any(|p| p.ends_with("listed twice")), "{:?}", loaded.problems);
    }

    #[test]
    fn a_definition_that_does_not_parse_is_refused() {
        let mut files = tree("alpha");
        files[1].1 = "schema_version = 99\n".to_string();
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems.iter().any(|p| p.starts_with("agents/alpha/definition.toml:")), "{:?}", loaded.problems);
    }

    #[test]
    fn an_unsafe_install_name_in_a_definition_refuses_the_entry() {
        let mut files = tree("alpha");
        files[1].1 = definition_toml("alpha").replace("test-alpha-cli", "x; calc");
        let loaded = load(&refs(&files));
        assert!(loaded.entries.is_empty());
        assert!(loaded.problems.iter().any(|p| p.contains("install.windows.npm")), "{:?}", loaded.problems);
    }

    #[test]
    fn the_windows_install_spec_is_read_only_when_it_validates() {
        let spec = windows_spec(&definition_toml("alpha")).expect("valid install");
        assert_eq!(spec.npm.as_deref(), Some("test-alpha-cli"));
        assert!(windows_spec(&definition_toml("alpha").replace("test-alpha-cli", "x; calc")).is_none());
        let without_install = definition_toml("alpha");
        let without_install = without_install.split("[install.windows]").next().expect("split");
        assert!(windows_spec(without_install).is_none());
        assert!(windows_spec("not toml [[").is_none());
    }

    #[test]
    fn the_version_is_eight_hex_digits_and_changes_when_a_byte_changes() {
        let a = [("agents/alpha/entry.toml", "x = 1\n")];
        let b = [("agents/alpha/entry.toml", "x = 2\n")];
        let v = version_of(&a);
        assert_eq!(v.len(), 8, "{v}");
        assert!(v.chars().all(|c| c.is_ascii_hexdigit()), "{v}");
        assert_eq!(v, version_of(&a));
        assert_ne!(v, version_of(&b));
    }

    #[test]
    fn the_version_does_not_depend_on_the_order_of_the_files() {
        let a = [("agents/alpha/entry.toml", "x = 1\n"), ("agents/beta/entry.toml", "y = 2\n")];
        let b = [("agents/beta/entry.toml", "y = 2\n"), ("agents/alpha/entry.toml", "x = 1\n")];
        assert_eq!(version_of(&a), version_of(&b));
    }

    #[test]
    fn the_version_cannot_be_fooled_by_moving_bytes_between_files() {
        assert_ne!(version_of(&[("a", "bc")]), version_of(&[("ab", "c")]));
    }

    #[test]
    fn an_unknown_id_is_none_everywhere() {
        assert!(get("no-such-agent").is_none());
        assert!(embedded_definition("no-such-agent").is_none());
        assert!(install_spec("no-such-agent").is_none());
        let loaded = load(&refs(&tree("alpha")));
        assert!(find_in(&loaded.entries, "beta").is_none());
        assert!(find_in(&loaded.entries, "alpha").is_some());
    }

    #[test]
    fn the_catalog_version_is_eight_hex_digits() {
        let v = catalog_version();
        assert_eq!(v.len(), 8, "{v}");
        assert!(v.chars().all(|c| c.is_ascii_hexdigit()), "{v}");
    }

    #[test]
    fn the_shipped_catalog_loads_with_no_problems_and_is_sorted() {
        assert!(problems().is_empty(), "{:?}", problems());
        assert!(all().windows(2).all(|w| w[0].entry.store.id < w[1].entry.store.id));
    }

    /// Every `.toml`, `.txt` and `.jsonl` file under `dir`, as `rel/...` paths.
    fn walk(dir: &std::path::Path, rel: &str, out: &mut Vec<String>) {
        for item in std::fs::read_dir(dir).expect("catalog folder exists") {
            let item = item.expect("readable entry");
            let name = item.file_name().to_string_lossy().into_owned();
            let rel_path = format!("{rel}/{name}");
            if item.path().is_dir() {
                walk(&item.path(), &rel_path, out);
            } else if [".toml", ".txt", ".jsonl"].iter().any(|ext| name.ends_with(ext)) {
                out.push(rel_path);
            }
        }
    }

    #[test]
    fn the_embedded_list_matches_the_catalog_folder_on_disk() {
        let mut on_disk = Vec::new();
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("catalog");
        walk(&root.join("agents"), "agents", &mut on_disk);
        on_disk.sort();
        let embedded: Vec<&str> = embedded::FILES.iter().map(|(path, _)| *path).collect();
        assert_eq!(embedded, on_disk, "run: node scripts/gen-store-catalog.mjs");
    }
}
